svg.script:
//!export-start
let _pn_count = 0;
let _ps_type = 'alarm';
let _pb_blinking = false;
let _pb_command = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.nAlerts = toNum(_pn_count);
    el.blinking = toBool(_pb_blinking);
    el.counter = true;
    el.alertType = toNum(_pn_count) > 0 ? String(_ps_type) : undefined;
}

function putValue(id, value) {
    if (id === '_pn_count') { _pn_count = toNum(value); }
    if (id === '_ps_type') { _ps_type = String(value); }
    if (id === '_pb_blinking') { _pb_blinking = toBool(value); }
    if (id === '_pb_command') { _pb_command = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

(function () {
    var el = document.getElementById('ob_el');
    if (!el) return;
    var timer = null;
    el.addEventListener('click', function (ev) {
        if (!(true)) return;
        _pb_command = true;
        __busyUntil = Date.now() + 1000;
        if (timer) { clearTimeout(timer); }
        timer = setTimeout(function () { timer = null; postValue('_pb_command', (_pb_command ? 1 : 0)); }, 0);
    });
})();

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 144;
    var h = parseFloat(root.getAttribute('height')) || 48;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);

}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

apply();
